import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoListSysMigration } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSysMigration";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validates a successful user registration (join) via the /auth/user/join API
 * endpoint.
 *
 * This test covers the happy path where a new user provides a unique, valid
 * email address, strong password, and required session context (href, referrer
 * URI, and ip [either v4/v6/null]). Test data is generated for maximum coverage
 * of type and format constraints.
 *
 * Steps:
 *
 * 1. Create a random user registration DTO (ITodoListUser.ICreate) with:
 *
 *    - Email: Globally unique (never used in previous registrations) and valid email
 *         format.
 *    - Password: Satisfies all length and format constraints, strong and random.
 *    - Href, referrer: Valid random URIs.
 *    - Ip: Randomly choose between IPv4, IPv6, or null (verify server handles all
 *         supported types).
 * 2. Call api.functional.auth.user.join(connection, { body })
 * 3. Assert that the response is ITodoListUser.IAuthorized, i.e., only public user
 *    info (id, email, created_at, updated_at) and a valid token object
 *    (ITodoListSysMigration) with correct field types and formats.
 * 4. Ensure no sensitive data (such as password or hash) is ever included in the
 *    response.
 * 5. Optionally, cross-validate that the user email in the response matches the
 *    one sent in request, timestamps have correct format, token fields are
 *    strings in expected JWT/date/time formats.
 */
export async function test_api_user_registration_success(
  connection: api.IConnection,
) {
  // Generate valid user registration data
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<
    string & tags.MinLength<8> & tags.MaxLength<100> & tags.Format<"password">
  >();
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();
  // Randomly pick ipv4, ipv6, or null for ip
  const ipOptions = [
    typia.random<string & tags.Format<"ipv4">>(),
    typia.random<string & tags.Format<"ipv6">>(),
    null,
  ] as const;
  const ip = RandomGenerator.pick(ipOptions);

  const requestBody = {
    email,
    password,
    href,
    referrer,
    ip,
  } satisfies ITodoListUser.ICreate;

  // Register user
  const result = await api.functional.auth.user.join(connection, {
    body: requestBody,
  });
  typia.assert(result);

  // Ensure response contains correct email, all required fields, and ONLY safe public attributes
  TestValidator.equals("response email matches input", result.email, email);
  TestValidator.predicate(
    "id is uuid format",
    typeof result.id === "string" && result.id.length === 36 /* UUID format */,
  );
  TestValidator.predicate(
    "created_at is ISO8601",
    typeof result.created_at === "string" && result.created_at.includes("T"),
  );
  TestValidator.predicate(
    "updated_at is ISO8601",
    typeof result.updated_at === "string" && result.updated_at.includes("T"),
  );
  TestValidator.predicate(
    "token is present and correctly structured",
    typeof result.token.access === "string" &&
      typeof result.token.refresh === "string" &&
      typeof result.token.expired_at === "string" &&
      typeof result.token.refreshable_until === "string",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoListSysMigration } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSysMigration";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Verifies duplicate email registration error handling in the user join API.
 *
 * This test first registers a user account using a valid random email and
 * password. It then attempts registration again using the exact same email. The
 * test confirms that:
 *
 * 1. The first registration succeeds and returns an authorized user response.
 * 2. The second (duplicate) registration attempt is rejected due to unique email
 *    constraint.
 * 3. The error response does not leak sensitive internal or debugging information.
 * 4. The API returns a generic error matching privacy/security requirements.
 * 5. No additional accounts are created for the duplicate email.
 *
 * Steps:
 *
 * 1. Generate valid registration input (matching ITodoListUser.ICreate specs).
 * 2. Call user join once (should succeed, authorized response).
 * 3. Call user join with the same input (should fail, proper error/exception
 *    returned).
 * 4. Confirm error handling by TestValidator.error and check error object shape
 *    does not contain raw SQL, full stacktrace, etc.
 */
export async function test_api_user_registration_duplicate_email(
  connection: api.IConnection,
) {
  // Step 1: Prepare valid registration input
  const userInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<
      string & tags.Format<"password"> & tags.MinLength<8> & tags.MaxLength<100>
    >(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    ip: RandomGenerator.pick([
      typia.random<string & tags.Format<"ipv4">>(),
      typia.random<string & tags.Format<"ipv6">>(),
      null,
      undefined,
    ]),
  } satisfies ITodoListUser.ICreate;

  // Step 2: Register user successfully
  const authorized = await api.functional.auth.user.join(connection, {
    body: userInput,
  });
  typia.assert(authorized);
  TestValidator.equals(
    "registered user email matches",
    authorized.email,
    userInput.email,
  );

  // Step 3: Attempt vulnerable duplicate registration (should fail with privacy/generic error)
  await TestValidator.error(
    "duplicate email registration is properly rejected",
    async () => {
      await api.functional.auth.user.join(connection, {
        body: userInput,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoListSysMigration } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSysMigration";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Validate successful login for a registered user with all required context
 * fields.
 *
 * The test ensures that:
 *
 * 1. A unique user is registered (join endpoint) with valid credentials and
 *    required context fields (href, referrer, ip)
 * 2. The login endpoint is called for that user using the same credentials/context
 * 3. The response contains JWT tokens, identity, and timestamps, all validated for
 *    structure
 * 4. Tokens are set and session context/auditing are logically trusted
 * 5. The returned profile corresponds to the registered account (matching email
 *    and structure)
 *
 * This covers the authentication happy-path and session context compliance. No
 * error/failure cases are exercised in this test.
 */
export async function test_api_user_login_success(connection: api.IConnection) {
  // Step 1: Prepare registration and login input data
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<
    string & tags.MinLength<8> & tags.MaxLength<100> & tags.Format<"password">
  >();
  const href = "https://example.com/join";
  const referrer = "https://test.referrer/landing";
  const ip: string | null = RandomGenerator.pick([
    typia.random<string & tags.Format<"ipv4">>(),
    typia.random<string & tags.Format<"ipv6">>(),
    null,
  ]);

  const joinBody = {
    email,
    password: password satisfies string,
    href,
    referrer,
    ip,
  } satisfies ITodoListUser.ICreate;
  const joined: ITodoListUser.IAuthorized = await api.functional.auth.user.join(
    connection,
    {
      body: joinBody,
    },
  );
  typia.assert(joined);
  TestValidator.equals("join email matches", joined.email, email);

  // Step 2: Login with the registered credentials and same session context
  const loginBody = {
    email,
    password: password satisfies string,
    href,
    referrer,
    ip,
  } satisfies ITodoListUser.ILogin;
  const loginResult: ITodoListUser.IAuthorized =
    await api.functional.auth.user.login(connection, {
      body: loginBody,
    });
  typia.assert(loginResult);

  // Step 3: Verify returned user details and tokens
  TestValidator.equals("login email matches", loginResult.email, email);
  TestValidator.predicate(
    "id is non-empty",
    typeof loginResult.id === "string" && loginResult.id.length > 0,
  );
  TestValidator.predicate(
    "created_at is iso date-time",
    typeof loginResult.created_at === "string" &&
      loginResult.created_at.includes("T"),
  );
  TestValidator.predicate(
    "updated_at is iso date-time",
    typeof loginResult.updated_at === "string" &&
      loginResult.updated_at.includes("T"),
  );
  typia.assert<ITodoListSysMigration>(loginResult.token);
  TestValidator.predicate(
    "jwt access token is non-empty",
    typeof loginResult.token.access === "string" &&
      loginResult.token.access.length > 0,
  );
  TestValidator.predicate(
    "jwt refresh token is non-empty",
    typeof loginResult.token.refresh === "string" &&
      loginResult.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "expired_at is iso date-time",
    typeof loginResult.token.expired_at === "string" &&
      loginResult.token.expired_at.includes("T"),
  );
  TestValidator.predicate(
    "refreshable_until is iso date-time",
    typeof loginResult.token.refreshable_until === "string" &&
      loginResult.token.refreshable_until.includes("T"),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoListSysMigration } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSysMigration";
import type { ITodoListUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListUser";

/**
 * Ensures that login with a valid email but incorrect password is securely
 * rejected.
 *
 * Business workflow:
 *
 * 1. Register a valid user with a random, unique email and strong password (plus
 *    required session context: href, referrer, ip)
 * 2. Attempt login with the same email but a random incorrect password (same
 *    length/complexity as a real password), and session context
 * 3. Assert that authentication fails: no tokens issued, no user info revealed,
 *    and only generic error presented (no info about which field was wrong).
 *
 * Steps:
 *
 * - Generate unique random email and password following all constraints
 * - Register the user via join endpoint
 * - Attempt login with same email and wrong password
 * - Assert login endpoint throws error
 * - Optionally, check that error reveals no sensitive details
 */
export async function test_api_user_login_wrong_password(
  connection: api.IConnection,
) {
  // Registration input
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<
    string & tags.MinLength<8> & tags.MaxLength<100> & tags.Format<"password">
  >();
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();
  const ip_candidates = [
    typia.random<string & tags.Format<"ipv4">>(),
    typia.random<string & tags.Format<"ipv6">>(),
  ];
  const ip = RandomGenerator.pick(ip_candidates);

  const joinInput = {
    email,
    password,
    href,
    referrer,
    ip,
  } satisfies ITodoListUser.ICreate;

  // Register user
  const registered = await api.functional.auth.user.join(connection, {
    body: joinInput,
  });
  typia.assert(registered);
  TestValidator.equals(
    "registered user email matches",
    registered.email,
    email,
  );

  // Wrong password (ensure it's different)
  let wrongPassword: string &
    tags.MinLength<8> &
    tags.MaxLength<128> &
    tags.Format<"password">;
  do {
    wrongPassword = typia.random<
      string & tags.MinLength<8> & tags.MaxLength<128> & tags.Format<"password">
    >();
  } while (wrongPassword === password);

  const loginInput = {
    email,
    password: wrongPassword,
    href,
    referrer,
    ip,
  } satisfies ITodoListUser.ILogin;

  // Attempt login with wrong password: must fail, must not leak info
  await TestValidator.error(
    "login with wrong password must fail with generic error",
    async () => {
      await api.functional.auth.user.login(connection, { body: loginInput });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ITodoListSysMigration } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoListSysMigration";
